<script setup>
import { computed, ref, watch } from 'vue'
import { Link, router } from '@inertiajs/vue3'
import AppLayout from '@/Layouts/AppLayout.vue'
import WallStatusFilters from '@/Components/WallStatusFilters.vue'
import WallStatusBadge from '@/Components/WallStatusBadge.vue'
import { filterWallRows } from '@/Support/wallLifecycle'
const props = defineProps({ items: { type: Array, default: () => [] }, prepared: Boolean, horizon: String, horizons: Object, completedSession: String, demonstration: Boolean, localDemoAvailable: Boolean })
const status = ref('all'), symbol = ref(''), direction = ref('all')
const noIdeas = computed(() => props.items.filter(row => row.status === 'no_idea'))
const rows = computed(() => props.items.filter(row => row.status !== 'no_idea').map(row => ({ ...row, status_group: !row.is_current && ['watching', 'conditions_met', 'in_progress'].includes(row.status_group) ? 'needs_update' : row.status_group })))
const visible = computed(() => filterWallRows(rows.value, { status: status.value, symbol: symbol.value, direction: direction.value }))
const latest = computed(() => props.items.map(row => row.reviewed_through).sort().at(-1))
const number = value => Number.isFinite(value) ? value.toLocaleString('en-US', { maximumFractionDigits: 2 }) : '—'
const percent = value => Number.isFinite(value) ? `${value > 0 ? '+' : ''}${number(value)}%` : '—'
const volatilityPercent = value => Number.isFinite(value) ? `${number(value * 100)}%` : '—'
const exposure = value => !Number.isFinite(value) ? '—' : new Intl.NumberFormat('en-US', { notation: 'compact', maximumFractionDigits: 2, signDisplay: 'exceptZero' }).format(value)
const switchHorizon = key => router.get('/swing-ideas', { horizon: key, ...(props.demonstration ? { demo: 1 } : {}) }, { preserveScroll: true })
watch(() => props.horizon, () => { status.value = 'all'; symbol.value = ''; direction.value = 'all' })
</script>
<template>
  <AppLayout title="Swing ideas">
    <main class="swing-page">
      <header class="swing-heading"><div><p class="eyebrow">MULTI-DAY RESEARCH</p><h1>Swing ideas</h1><p>Find a level to watch, the price confirmation you need and where the idea ends.</p></div><Link href="/scanner?scan=activity">Looking for intraday setups? Open Scanner →</Link></header>
      <div v-if="demonstration" class="swing-intro" role="status"><strong>Local demonstration · Synthetic examples</strong><p>These examples show the interface and lifecycle. They are not market ideas and are never saved or sent as alerts.</p><Link :href="`/swing-ideas?horizon=${horizon}`">Back to saved symbols →</Link></div>
      <p v-else-if="localDemoAvailable"><Link :href="`/swing-ideas?horizon=${horizon}&demo=1`">Preview local examples of every status →</Link></p>
      <nav class="swing-horizons" aria-label="Swing holding period"><button v-for="(profile, key) in horizons" :key="key" type="button" :aria-pressed="horizon === key" @click="switchHorizon(key)">{{ profile.label }}</button></nav>
      <p class="swing-scope">Holding period: {{ horizons[horizon].label }} · Options context: {{ horizons[horizon].scope_label }} expiries · Updated from completed EOD data</p>
      <p v-if="latest" class="swing-updated">Reviewed through {{ latest }}<span v-if="latest !== completedSession"> · Recorded research view</span></p>
      <div class="swing-intro"><strong>A plan becomes qualified only after its price conditions pass.</strong><p>Watching plans have no confirmed entry. Targets and invalidation are underlying prices. These reviews do not assume an entered position or estimate option profit.</p></div>
      <WallStatusFilters v-model="status" v-model:symbol="symbol" v-model:direction="direction" :rows="rows" />
      <div v-if="!prepared || !items.length" class="swing-empty"><h2>Your swing plans are being prepared.</h2><p>Plans will appear here for your saved symbols after their EOD review. Intraday wall activity remains available in Scanner.</p><Link href="/scanner?scan=activity">Open Scanner →</Link></div>
      <p v-else-if="!rows.length" class="swing-empty" role="status">No qualifying swing plans in this EOD review. {{ noIdeas.length }} saved symbols reviewed. Open the reasons below or continue watching intraday activity in Scanner.</p>
      <p v-else-if="!visible.length" class="swing-empty" role="status">No ideas match these filters. The selected filters stay in place.</p>
      <div v-else class="swing-grid">
        <article v-for="idea in visible" :key="idea.id" class="swing-card" :class="`swing-card--${idea.direction || 'neutral'}`">
          <header><div><span class="swing-symbol">{{ idea.symbol }}</span><span v-if="idea.direction" :class="idea.direction">{{ idea.direction === 'bullish' ? 'Bullish' : 'Bearish' }} reclaim watch</span><span v-else>No qualifying plan</span></div><WallStatusBadge :status="idea.status_group" :outcome="idea.outcome" /></header>
          <p class="swing-date">Plan from {{ idea.source_date }} · Reviewed through {{ idea.reviewed_through }}</p>
          <p class="swing-reason">{{ idea.reason }}</p>
          <template v-if="idea.levels">
            <div class="swing-trigger"><span>{{ idea.status_group === 'watching' ? 'What price must do' : 'Original price condition' }}</span><p>Test {{ number(idea.levels.touch_low) }}–{{ number(idea.levels.touch_high) }}, then post a daily close {{ idea.direction === 'bullish' ? 'above' : 'below' }} {{ number(idea.levels.trigger) }} inside the entry area.</p></div>
            <dl class="swing-levels"><div><dt>Entry area after confirmation</dt><dd>{{ number(idea.levels.entry_low) }}–{{ number(idea.levels.entry_high) }}</dd></div><div><dt>Reference target</dt><dd>{{ number(idea.levels.target) }}</dd></div><div><dt>Invalid if daily close</dt><dd>{{ idea.levels.invalidation_side }} {{ number(idea.levels.invalidation) }}</dd></div><div><dt>Entry deadline</dt><dd>{{ idea.entry_deadline }}</dd></div></dl>
            <p v-if="idea.qualified_at" class="swing-qualified">Conditions met {{ idea.qualified_at }} at close {{ number(idea.qualified_price) }}<span v-if="idea.deadline"> · Review ends by {{ idea.deadline }}</span></p>
            <div class="swing-why"><h3>Why this is on the list</h3><p>{{ idea.direction === 'bullish' ? 'Price and its 20-day average are above the 50-day trend.' : 'Price and its 20-day average are below the 50-day trend.' }} The watched wall is near price, with a recorded opposing target and {{ number(idea.evidence.target_room_ratio) }}× room versus invalidation distance.</p></div>
          </template>
          <details class="swing-evidence"><summary>Price, positioning and volatility</summary><dl><div><dt>EOD close</dt><dd>{{ number(idea.evidence.close) }}</dd></div><div><dt>20-day / 50-day average</dt><dd>{{ number(idea.evidence.sma20) }} / {{ number(idea.evidence.sma50) }}</dd></div><div><dt>Average daily range · ATR14</dt><dd>{{ number(idea.evidence.atr14) }}</dd></div><div><dt>Five-session price change</dt><dd>{{ percent(idea.evidence.return5_pct) }}</dd></div><div><dt>Net GEX · USD / 1% move</dt><dd>{{ exposure(idea.evidence.net_gex) }}</dd></div><div><dt>DEX · share equivalents</dt><dd>{{ exposure(idea.evidence.dex_shares) }}</dd></div><div><dt>1M IV / 20-day realized vol</dt><dd>{{ volatilityPercent(idea.evidence.volatility?.iv1m) }} / {{ volatilityPercent(idea.evidence.volatility?.rv20) }}</dd></div><div v-if="idea.evidence.oi_change"><dt>OI change at watched wall</dt><dd>{{ percent(idea.evidence.oi_change.pct) }} · {{ exposure(idea.evidence.oi_change.contracts) }} contracts</dd></div><div v-if="Number.isFinite(idea.evidence.target_rolloff_pct)"><dt>Target exposure expiring before maximum exit</dt><dd>{{ number(idea.evidence.target_rolloff_pct) }}%</dd></div></dl><p>GEX, DEX and OI describe exposure, not who bought or sold. Exposure alone does not confirm a direction.</p></details>
          <p v-if="idea.levels" class="swing-events">{{ idea.event_review }}</p>
          <footer><Link :href="`/dashboard?symbol=${encodeURIComponent(idea.symbol)}&mode=eod&tab=positioning&timeframe=${idea.scope_label === '1M' ? '30d' : '90d'}&view=latest_eod`">Open EOD analysis →</Link><Link :href="`/dashboard?symbol=${encodeURIComponent(idea.symbol)}&mode=intraday&tab=walls&timeframe=7d`">Inspect intraday price response →</Link></footer>
        </article>
      </div>
      <details v-if="noIdeas.length" class="swing-guide"><summary>{{ noIdeas.length }} symbols without a qualifying plan · Why?</summary><div v-for="idea in noIdeas" :key="idea.id" class="swing-no-idea"><strong>{{ idea.symbol }}</strong><p>{{ idea.reason }}</p></div></details>
      <details class="swing-guide"><summary>How to use Swing ideas</summary><p>Start with Watching. A wall test is followed by a daily close inside the recorded entry area. Conditions met is recorded after that close. Check current price before considering an entry. In progress follows subsequent daily closes with the original levels fixed. Past setups lists scenarios whose comparison has ended. Each card names the outcome, such as Target reached, Invalidated or Setup window closed.</p><p>The 2–5 day view reviews a qualified scenario for up to five sessions; the 1–3 week view uses up to fifteen. These are initial research rules, not validated win rates. Overnight gaps can move price past a level. Equity plans require your earnings and event review. No swing notifications are sent by this version.</p></details>
    </main>
  </AppLayout>
</template>
<style scoped>
