y,.swing-guide summary{cursor:pointer;font-size:.82rem;color:#d6e5ff;padding-block:5px}.swing-evidence dl{display:grid;gap:12px;margin:16px 0}.swing-evidence dl div{display:flex;justify-content:space-between;align-items:baseline;gap:14px}.swing-evidence dd{font-size:.8rem;text-align:right}.swing-events{font-size:.74rem;margin-top:18px}.swing-card footer{display:flex;gap:16px;flex-wrap:wrap;margin-top:18px}.swing-empty{border:1px solid #43516b;border-radius:10px;padding:30px;margin-top:20px;background:#1b2131}.swing-empty h2{font-size:1.1rem;font-weight:650}.swing-guide{padding:20px;background:#1b2131;border-radius:8px;margin-top:28px}button:focus-visible,a:focus-visible,summary:focus-visible{outline:2px solid #b5bcff;outline-offset:3px}@media(max-width:900px){.swing-grid{grid-template-columns:1fr}}@media(max-width:550px){.swing-page{padding:22px 14px 40px}.swing-card{padding:17px}.swing-levels{gap:15px}.swing-horizons button{padding:10px 13px}.swing-evidence dl div{align-items:start;flex-direction:column;gap:2px}.swing-evidence dd{text-align:left}}
</style>
